-- Rajasthan-specific service, FAQ and editorial content. This migration is intentionally separate
-- so existing Supabase projects can apply the content refresh without rebuilding their schema.
on conflict(slug) do update set title=excluded.title,short_description=excluded.short_description,description=excluded.description,benefits=excluded.benefits,features=excluded.features,image_url=excluded.image_url,seo_title=excluded.seo_title,meta_description=excluded.meta_description,published=true;

update public.faqs set answer='System sizing starts with recent bills, your connection details and usable roof area. A site visit then checks shading, orientation, structure, electrical conditions, safe access and local requirements before a final size is recommended.' where question='How do I know what size solar system I need?';
update public.faqs set answer='We can discuss technical readiness and help you prepare questions about the process. Eligibility, approved vendors, subsidy values and timelines must be verified against current official programme information.' where question='Can you help with the PM Surya Ghar subsidy process?';
update public.faqs set answer='The schedule depends on system size, site readiness, approvals, equipment and the work window. A project-specific sequence is shared after the survey and scope review.' where question='How long does installation take?';
select v.question,v.answer,v.category,v.sort_order,true from (values
('Does Rajasthan dust change the solar design?','Dust and soiling can reduce light reaching the modules, and hot module temperatures affect output. The design discussion should consider roof tilt, safe cleaning access, maintenance responsibility and equipment clearances. Cleaning frequency should follow site conditions and equipment guidance—not a generic promise.','Rajasthan planning',9),
('Which electricity company handles my rooftop application?','The DISCOM serving the exact consumer meter determines the application and metering route. Check the company name and consumer number on your latest bill, then verify the current process on that DISCOM and the official national rooftop portal.','Rajasthan planning',10),
('Is a solar savings estimate a guaranteed saving?','No. An estimate depends on expected generation, self-consumption, tariff, export settlement, weather, shading, equipment and system availability. A bill review and site assessment are needed for a project-specific estimate.','Planning',11)
) as v(question,answer,category,sort_order) where not exists(select 1 from public.faqs f where f.question=v.question);

on conflict(slug) do nothing;

on conflict(slug) do update set title=excluded.title,status='published',content=excluded.content,updated_at=now();
